// Read DATABASE_URL from .env.test
class DatabaseConnection {
  constructor() {
    this.pool = null;
    this.init();
  }

  init() {
    const databaseUrl = process.env.DATABASE_URL;

    if (!databaseUrl) {
      console.error('DATABASE_URL is not defined in .env.test');
      return;
    }

    try {
      this.pool = new Pool({
        connectionString: databaseUrl,
        ssl: {
          rejectUnauthorized: false // Adjust based on your DB SSL requirements
        }
      });

      this.pool.on('connect', () => {
        console.log('Database pool connected');
      });

      this.pool.on('error', (err) => {
        console.error('Unexpected error on idle client', err);
        process.exit(-1);
      });
    } catch (error) {
      console.error('Failed to create pool:', error.message);
    }
  }

  async healthCheck() {
    if (!this.pool) {
      return { success: false, message: 'Database pool not initialized' };
    }

    try {
      await this.pool.query('SELECT 1');
      return { success: true, message: 'Database connection healthy' };
    } catch (error) {
      return { success: false, message: `Health check failed: ${error.message}` };
    }
  }

  getPool() {
    return this.pool;
  }
}

const db = new DatabaseConnection();

module.exports = db;
